contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take arrays as calldata to avoid copying; the function is not payable.
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        // require matching non-empty arrays so loop executes and lengths align
        require(_tos.length == v.length && _tos.length > 0);

        // Call transfer as the authorized sender: deployer of C set from address is hardcoded,
        // but msg.sender when calling c.transfer will be this contract. The only way to satisfy
        // the contract's require(msg.sender == from) is if c was deployed with from == address(this).
        // We cannot change c here, so the call may revert; capture revert and return value.
        bool reverted;
        bool ret;
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // Read public getters after the call
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule: if the call returned (did not revert) and returned true, then the public
        // getters from and caddress must be unchanged (they are never modified by transfer),
        // and the call must have returned true. Expressed as: if not reverted then ret==true
        // and from and caddress equal their observed values (no change compared to themselves).
        // This becomes: (!reverted) implies (ret == true && after_from == after_from && after_caddress == after_caddress)
        // Simplify to: !reverted ==> ret == true
        // Also avoid tautological self-equality by only asserting the meaningful property.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

