contract InvMutTest {
    C c;
    address owner;

    constructor(C _c) { c = _c; owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9; }

    // single public entry that encodes the property check
    function run(address[] calldata _tos, uint[] calldata v, bool callAsOwner) public payable {
        require(_tos.length == v.length);
        // read observable public state before
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        // perform call either as allowed owner or as this contract (which will not be the owner)
        if (callAsOwner) {
            // We need to call c.transfer as the owner address. The checker deploys c and this contract
            // as caller; we cannot change msg.sender, so we instead assert that if msg.sender equals owner,
            // the call should succeed. Here we simulate both paths by calling and catching revert.
            try c.transfer(_tos, v) returns (bool ok) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transfer(_tos, v) returns (bool ok) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observable public state after
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule:
        // - The public addresses `from` and `caddress` never change as a result of transfer calls
        // - Additionally, if the caller is not the configured owner, the call must revert.
        if (msg.sender != owner) {
            assert(reverted && before_from == after_from && before_caddress == after_caddress);
        } else {
            // when msg.sender is the owner, the function must not change public addresses (it may or may not revert due to other reasons,
            // but in the intended contract it should return true; we assert only that addresses remain unchanged and if the call did not revert,
            // it returned true. We captured revert flag; if not reverted we assume success and require addresses unchanged.
            if (!reverted) {
                assert(before_from == after_from && before_caddress == after_caddress);
            } else {
                // if it reverted even when owner, still addresses must be unchanged
                assert(before_from == after_from && before_caddress == after_caddress);
            }
        }
    }

    receive() external payable {}
}
